  } else {
    process.kill("SIGTERM");
  }
  await exited;
}

async function jsonRecord(response: Response): Promise<JsonRecord> {
  const body: unknown = await response.json();
  if (!isRecord(body)) throw new Error(`expected JSON object from ${response.url}`);
